const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class TodoWorld {
  constructor() {
    this.window = null;
    this.document = null;
  }

  loadApp() {
    const htmlPath = path.join(__dirname, '..', '..', 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf-8');

    this.window = new Window({ url: 'http://localhost/' });
    this.document = this.window.document;
    this.document.write(html);
    this.document.close();

    // Execute todomvc-common base.js
    const basePath = path.join(__dirname, '..', '..', 'node_modules', 'todomvc-common', 'base.js');
    const baseCode = fs.readFileSync(basePath, 'utf-8');
    this.window.eval(baseCode);

    // Execute app.js
    const appPath = path.join(__dirname, '..', '..', 'js', 'app.js');
    const appCode = fs.readFileSync(appPath, 'utf-8');
    this.window.eval(appCode);
  }

  get newTodoInput() {
    return this.document.querySelector('.new-todo');
  }

  get todoList() {
    return this.document.querySelectorAll('.todo-list li');
  }

  get todoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  findTodo(title) {
    return this.todoItems.find(li => {
      const label = li.querySelector('.view label');
      return label && label.textContent.trim() === title;
    });
  }

  typeInInput(input, text) {
    input.focus();
    input.value = text;
    input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  }

  pressEnter(input) {
    const event = new this.window.KeyboardEvent('keydown', {
      key: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true
    });
    input.dispatchEvent(event);
  }

  pressEscape(input) {
    const event = new this.window.KeyboardEvent('keydown', {
      key: 'Escape',
      keyCode: 27,
      which: 27,
      bubbles: true
    });
    input.dispatchEvent(event);
  }

  reloadApp() {
    const todos = this.getTodosFromStorage();
    this.loadApp();
    this.setTodosToStorage(todos);
    // Re-trigger route handling after reload
    this.window.location.reload = () => {
      this.loadApp();
      // Storage persists between reloads in happy-dom
      window.dispatchEvent(new this.window.Event('load'));
    };
    // Trigger a hashchange to re-apply the route
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  getTodosFromStorage() {
    try {
      return JSON.parse(this.window.localStorage.getItem('todos-shakedown') || '[]');
    } catch {
      return [];
    }
  }

  setTodosToStorage(todos) {
    this.window.localStorage.setItem('todos-shakedown', JSON.stringify(todos));
  }

  navigateTo(route) {
    this.window.location.hash = route;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  destroy() {
    if (this.window) {
      this.window.close();
      this.window = null;
      this.document = null;
    }
  }
}

setWorldConstructor(TodoWorld);

Before(function () {
  this.loadApp();
});

After(function () {
  this.destroy();
});

