(function () {
  'use strict';

  var STORAGE_KEY = 'todos-shakedown';
  var todoList = document.querySelector('.todo-list');
  var newTodoInput = document.querySelector('.new-todo');
  var toggleAllCheckbox = document.querySelector('.toggle-all');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var counter = document.querySelector('.todo-count');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var filterLinks = document.querySelectorAll('.filters a');

  function getTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function getCurrentRoute() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function renderTodos() {
    var todos = getTodos();
    var route = getCurrentRoute();

    todoList.innerHTML = '';

    todos.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;

      if (todo.completed) {
        li.classList.add('completed');
      }

      var divView = document.createElement('div');
      divView.className = 'view';

      var checkbox = document.createElement('input');
      checkbox.className = 'toggle';
      checkbox.type = 'checkbox';
      checkbox.checked = todo.completed;
      checkbox.addEventListener('change', function () {
        todo.completed = checkbox.checked;
        saveTodos(todos);
        renderTodos();
      });

      var label = document.createElement('label');
      label.textContent = todo.title;
      label.addEventListener('dblclick', function () {
        li.classList.add('editing');
        var editInput = li.querySelector('.edit');
        if (editInput) {
          editInput.focus();
          editInput.selectionStart = editInput.value.length;
        }
      });

      var destroyBtn = document.createElement('button');
      destroyBtn.className = 'destroy';
      destroyBtn.addEventListener('click', function () {
        var idx = todos.indexOf(todo);
        if (idx > -1) {
          todos.splice(idx, 1);
          saveTodos(todos);
          renderTodos();
        }
      });

      divView.appendChild(checkbox);
      divView.appendChild(label);
      divView.appendChild(destroyBtn);

      var editInput = document.createElement('input');
      editInput.className = 'edit';
      editInput.value = todo.title;

      editInput.addEventListener('blur', function () {
        if (!li.classList.contains('editing')) return;
        saveEdit(todo, editInput, li, todos);
      });

      editInput.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' || e.keyCode === 13) {
          e.preventDefault();
          if (li.classList.contains('editing')) {
            saveEdit(todo, editInput, li, todos);
          }
        } else if (e.key === 'Escape' || e.keyCode === 27) {
          li.classList.remove('editing');
          editInput.value = todo.title;
        }
      });

      li.appendChild(divView);
      li.appendChild(editInput);
      todoList.appendChild(li);
    });

    updateVisibility(todos);
    updateCounter(todos);
    updateToggleAll(todos);
    updateClearCompleted(todos);
    updateFilterLinks();

    // Apply route filter visibility
    applyRouteFilter(todos, route);
  }

  function saveEdit(todo, editInput, li, todos) {
    li.classList.remove('editing');
    var newTitle = editInput.value.trim();
    if (newTitle === '') {
      var idx = todos.indexOf(todo);
      if (idx > -1) {
        todos.splice(idx, 1);
      }
    } else {
      todo.title = newTitle;
    }
    saveTodos(todos);
    renderTodos();
  }

  function updateVisibility(todos) {
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footer.style.display = '';
    }
  }

  function updateCounter(todos) {
    var activeCount = todos.filter(function (t) {
      return !t.completed;
    }).length;
    var itemText = activeCount === 1 ? 'item' : 'items';
    counter.innerHTML = '<strong>' + activeCount + '</strong> ' + itemText + ' left';
  }

  function updateToggleAll(todos) {
    if (todos.length === 0) {
      toggleAllCheckbox.checked = false;
      return;
    }
    toggleAllCheckbox.checked = todos.every(function (t) {
      return t.completed;
    });
  }

  function updateClearCompleted(todos) {
    var hasCompleted = todos.some(function (t) {
      return t.completed;
    });
    clearCompletedBtn.style.display = hasCompleted ? '' : 'none';
  }

  function updateFilterLinks() {
    var route = getCurrentRoute();
    filterLinks.forEach(function (link) {
      if (link.getAttribute('href') === '#/' && route === 'all') {
        link.classList.add('selected');
      } else if (link.getAttribute('href') === '#/active' && route === 'active') {
        link.classList.add('selected');
      } else if (link.getAttribute('href') === '#/completed' && route === 'completed') {
        link.classList.add('selected');
      } else {
        link.classList.remove('selected');
      }
    });
  }

  function applyRouteFilter(todos, route) {
    var items = todoList.querySelectorAll('li');
    items.forEach(function (li) {
      var id = li.dataset.id;
      var todo = todos.find(function (t) {
        return t.id === id;
      });
      if (!todo) return;

      if (route === 'active') {
        li.style.display = todo.completed ? 'none' : '';
      } else if (route === 'completed') {
        li.style.display = todo.completed ? '' : 'none';
      } else {
        li.style.display = '';
      }
    });
  }

  // Add todo
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.keyCode === 13) {
      var title = newTodoInput.value.trim();
      if (title === '') return;

      var todos = getTodos();
      todos.push({
        id: Date.now().toString(36) + Math.random().toString(36).substr(2, 5),
        title: title,
        completed: false
      });
      saveTodos(todos);
      newTodoInput.value = '';
      renderTodos();
    }
  });

  // Toggle all
  toggleAllCheckbox.addEventListener('change', function () {
    var todos = getTodos();
    var allCompleted = todos.every(function (t) {
      return t.completed;
    });
    todos.forEach(function (t) {
      t.completed = !allCompleted;
    });
    saveTodos(todos);
    renderTodos();
  });

  // Clear completed
  clearCompletedBtn.addEventListener('click', function () {
    var todos = getTodos().filter(function (t) {
      return !t.completed;
    });
    saveTodos(todos);
    renderTodos();
  });

  // Routing
  window.addEventListener('hashchange', function () {
    renderTodos();
  });

  // Initial render
  renderTodos();
})();

